    "memory/polymorphism": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Generic code can dispatch on the selected memory form.</span>\n<span data-k=\"comment\">* Iteration preserves access and ownership in the yielded value.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">struct</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span>\n    x<span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span>\n    y<span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> points<span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// default iteration yields ordinary values</span>\nfor <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> point of points<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    point <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// readonly iteration preserves readonly access</span>\nfor <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> point of <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> points<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    point <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// exclusive iteration permits mutation of each item</span>\nfor <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> point of <span data-k=\"punct\">&amp;</span>exclusive points<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    point <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// owned iteration consumes the owner</span>\nfor <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> point of ^points<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    point <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
